import {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  WidthType, BorderStyle, AlignmentType, HeadingLevel
} from "docx";
import { writeFileSync } from "fs";

const border = { style: BorderStyle.SINGLE, size: 1, color: "999999" };
const cellBorders = { top: border, bottom: border, left: border, right: border };

function row(label, value) {
  return new TableRow({
    children: [
      new TableCell({
        borders: cellBorders,
        width: { size: 3000, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun({ text: label, bold: true })] })],
      }),
      new TableCell({
        borders: cellBorders,
        width: { size: 6000, type: WidthType.DXA },
        children: [new Paragraph(value)],
      }),
    ],
  });
}

const doc = new Document({
  sections: [{
    children: [
      new Paragraph({
        heading: HeadingLevel.HEADING_1,
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Travel Summary", bold: true })],
      }),
      new Paragraph({ text: "" }),
      new Paragraph({
        heading: HeadingLevel.HEADING_2,
        children: [new TextRun({ text: "Airline Reservation" })],
      }),
      new Paragraph({ text: "" }),
      new Table({
        rows: [
          row("Confirmation Code", "B75309"),
          row("Flight Number",     "FL398507"),
          row("Trip Type",         "One-Way"),
          row("Class",             "Economy"),
          row("Origin",            "LAX (Los Angeles)"),
          row("Destination",       "LAS (Las Vegas)"),
          row("Date",              "2026-09-16"),
          row("Amount Paid",       "$129.00"),
          row("Payment Method",    "Visa credit card ending in cc_9cdfc95d"),
        ],
      }),
    ],
  }],
});

const buf = await Packer.toBuffer(doc);
writeFileSync("travel_summary.docx", buf);
console.log("Created travel_summary.docx");
